"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import type { DiaxRelation } from "diax";
import {
  Activity,
  Braces,
  Database,
  FileType2,
  Gauge,
  GitBranch,
  LayoutDashboard,
  PackageSearch,
  PieChart,
  ShieldAlert,
  ShieldCheck,
  Webhook,
} from "lucide-react";
import type { KeyboardEvent, ReactNode } from "react";

const targets = {
  snapshot: "snapshot-function",
  sync: "project-sync",
  table: "snapshot-table",
  dashboard: "output-dashboard",
  statistics: "output-statistics",
  webhook: "output-webhook",
} as const;

const sources = [
  {
    id: "source-sonar",
    moduleId: "module-sonar",
    name: "SonarQube",
    module: "SonarModule",
    table: "sonar_security_quality_metrics",
    tone: "blue",
    icon: ShieldCheck,
  },
  {
    id: "source-oxlint",
    moduleId: "module-oxlint",
    name: "Oxlint",
    module: "OxlintModule",
    table: "oxlint_report",
    tone: "green",
    icon: Braces,
  },
  {
    id: "source-sca",
    moduleId: "module-sca",
    name: "SCA",
    module: "ScaService",
    table: "security_sca",
    tone: "orange",
    icon: PackageSearch,
  },
  {
    id: "source-malware",
    moduleId: "module-malware",
    name: "Malware Scan",
    module: "MaliceService",
    table: "security_scan",
    tone: "red",
    icon: ShieldAlert,
  },
  {
    id: "source-types",
    moduleId: "module-types",
    name: "Type Coverage",
    module: "TCModule",
    table: "type_coverage_report",
    tone: "violet",
    icon: FileType2,
  },
] as const;

type Tone = (typeof sources)[number]["tone"];

const toneClasses: Record<Tone, { border: string; icon: string; label: string; field: string }> = {
  blue: {
    border: "border-sky-400/35",
    icon: "text-sky-300",
    label: "border-sky-300/30 bg-sky-400/10 text-sky-200",
    field: "border-sky-400/25 bg-sky-400/5 text-sky-200",
  },
  green: {
    border: "border-emerald-400/35",
    icon: "text-emerald-300",
    label: "border-emerald-300/30 bg-emerald-400/10 text-emerald-200",
    field: "border-emerald-400/25 bg-emerald-400/5 text-emerald-200",
  },
  orange: {
    border: "border-orange-400/35",
    icon: "text-orange-300",
    label: "border-orange-300/30 bg-orange-400/10 text-orange-200",
    field: "border-orange-400/25 bg-orange-400/5 text-orange-200",
  },
  red: {
    border: "border-rose-400/35",
    icon: "text-rose-300",
    label: "border-rose-300/30 bg-rose-400/10 text-rose-200",
    field: "border-rose-400/25 bg-rose-400/5 text-rose-200",
  },
  violet: {
    border: "border-violet-400/35",
    icon: "text-violet-300",
    label: "border-violet-300/30 bg-violet-400/10 text-violet-200",
    field: "border-violet-400/25 bg-violet-400/5 text-violet-200",
  },
};

const edgeColors: Record<Tone, string> = {
  blue: "#38bdf8",
  green: "#34d399",
  orange: "#fb923c",
  red: "#fb7185",
  violet: "#a78bfa",
};

const relations: readonly DiaxRelation<ReactNode>[] = [
  ...sources.map((source) => ({
    id: `${source.id}-ingest`,
    from: source.id,
    to: source.moduleId,
    label: <IngestLabel tone={source.tone} />,
    color: edgeColors[source.tone],
    targetMarker: "arrow" as const,
    gap: 5,
  })),
  ...sources.map((source) =>
    edge(`${source.moduleId}-snapshot`, source.moduleId, targets.snapshot, "#64748b"),
  ),
  edge("snapshot-write", targets.snapshot, targets.table, "#38bdf8", {
    label: <FlowLabel>durable write</FlowLabel>,
  }),
  edge("sync-write", targets.sync, targets.table, "#a78bfa"),
  edge("table-dashboard", targets.table, targets.dashboard, "#38bdf8"),
  edge("table-statistics", targets.table, targets.statistics, "#34d399"),
  edge("table-webhook", targets.table, targets.webhook, "#fb923c", {
    label: <FlowLabel>async event</FlowLabel>,
    style: "dashed",
  }),
];

function edge(
  id: string,
  from: string,
  to: string,
  color: string,
  options: Partial<Exclude<DiaxRelation<ReactNode>, string>> = {},
): DiaxRelation<ReactNode> {
  return { id, from, to, color, targetMarker: "arrow", gap: 5, ...options };
}

const snapshotFields = [
  { label: "Sonar", fields: "bugs · vulnerabilities · hotspots", tone: "blue" },
  { label: "Oxlint", fields: "errors · warnings", tone: "green" },
  { label: "SCA", fields: "critical · high · medium · low", tone: "orange" },
  { label: "Malware", fields: "issue_count", tone: "red" },
  { label: "TypeCov", fields: "percent · correct · total", tone: "violet" },
] as const;

const outputs = [
  {
    id: targets.dashboard,
    title: "Dashboard",
    detail: "Paginated reads · 0 report joins",
    icon: LayoutDashboard,
  },
  {
    id: targets.statistics,
    title: "Statistics",
    detail: "COUNT · GROUP BY · distributions",
    icon: PieChart,
  },
  {
    id: targets.webhook,
    title: "Webhook",
    detail: "Alerts · weekly reports",
    icon: Webhook,
  },
] as const;

const endpointClass =
  "relative min-w-0 border border-slate-700 bg-[#14212b] shadow-[0_12px_28px_rgb(0_0_0_/_0.24)]";

export default function SnapshotFanIn() {
  return (
    <figure
      data-showcase-corpus="snapshot-fan-in"
      className="w-full max-w-[1120px] overflow-hidden rounded-xl border border-slate-800 bg-[#070d12] p-3 text-slate-100 shadow-[0_24px_70px_rgb(0_0_0_/_0.3)] sm:p-6"
    >
      <figcaption className="mb-5 flex flex-col justify-between gap-3 border-b border-slate-800 pb-4 sm:flex-row sm:items-end">
        <div>
          <p className="m-0 font-mono text-[9px] font-bold uppercase tracking-[0.14em] text-[#41a6b9]">
            Dense fan-in · Authored DOM
          </p>
          <h2 className="m-0 mt-1 text-xl font-semibold tracking-[-0.035em] sm:text-3xl">
            T+0 quality snapshot pipeline
          </h2>
          <p className="m-0 mt-1 text-[10px] leading-relaxed text-slate-400 sm:text-xs">
            5 independent reports converge into one read model, then fan out to 3 products.
          </p>
        </div>
        <dl className="m-0 flex gap-4 font-mono text-[8px] text-slate-400">
          <Stat label="Targets" value="16" />
          <Stat label="Relations" value="15" />
          <Stat label="Manual anchors" value="0" />
        </dl>
      </figcaption>

      <RelationLegend />

      <div className="my-4 grid gap-2 sm:grid-cols-2">
        <Comparison
          state="Before"
          title="Read-time report joins"
          query="5 subqueries + 5 joins"
          detail="Long dependency chain and slow pagination"
          tone="bad"
        />
        <Comparison
          state="After"
          title="Write-time snapshot refresh"
          query="0 subqueries + 0 report joins"
          detail="One deterministic row for every project and branch"
          tone="good"
        />
      </div>

      <section
        data-diax-reading-canvas
        className="overflow-x-auto rounded-lg border border-slate-800 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#41a6b9]"
        aria-label="Scrollable quality snapshot architecture"
        // biome-ignore lint/a11y/noNoninteractiveTabindex: this overflow region remains keyboard-scrollable across browsers.
        tabIndex={0}
        onKeyDown={scrollTopologyOnArrow}
      >
        <ConnectionSurface
          relations={relations}
          aria-label="Quality snapshot fan-in relationships"
          className="min-w-[1040px] overflow-hidden bg-[#0b141b] p-6 pb-14 [background-image:linear-gradient(rgb(65_166_185_/_0.04)_1px,transparent_1px),linear-gradient(90deg,rgb(65_166_185_/_0.04)_1px,transparent_1px)] [background-size:24px_24px]"
        >
          <section aria-labelledby="report-intake-title">
            <StageHeading
              number="01"
              id="report-intake-title"
              title="Report intake"
              detail="Every scanner keeps its own payload and write lifecycle"
            />
            <div className="mt-4 grid grid-cols-5 gap-3">
              {sources.map((source) => (
                <div key={source.id} className="grid grid-rows-[auto_68px_auto]">
                  <SourceCard source={source} />
                  <span aria-hidden="true" />
                  <ModuleCard source={source} />
                </div>
              ))}
            </div>
          </section>

          <section className="mt-24" aria-labelledby="refresh-title">
            <StageHeading
              number="02"
              id="refresh-title"
              title="Deterministic refresh"
              detail="Report writes and project metadata meet before the read model"
            />
            <div className="mx-auto mt-5 grid max-w-[760px] grid-cols-2 gap-5">
              <article
                {...connectionTarget(targets.snapshot)}
                className={`${endpointClass} rounded-lg border-sky-400/35 p-4`}
              >
                <Activity aria-hidden="true" className="size-4 text-sky-300" />
                <h3 className="m-0 mt-2 font-mono text-xs font-semibold text-sky-200">
                  updateSnapshotForRecord()
                </h3>
                <p className="m-0 mt-1 text-[9px] text-slate-400">recordId · reportType</p>
                <code className="mt-3 block rounded border border-orange-400/25 bg-orange-400/5 p-2 text-[8px] text-orange-200">
                  branch === project.defaultBranch
                </code>
              </article>
              <article
                {...connectionTarget(targets.sync)}
                className={`${endpointClass} rounded-lg border-violet-400/35 p-4`}
              >
                <GitBranch aria-hidden="true" className="size-4 text-violet-300" />
                <h3 className="m-0 mt-2 text-xs font-semibold">CMDB + GitLab Sync</h3>
                <p className="m-0 mt-1 text-[9px] text-slate-400">Scheduled metadata refresh</p>
                <code className="mt-3 block rounded border border-violet-400/25 bg-violet-400/5 p-2 text-[8px] text-violet-200">
                  riskLevel · department · defaultBranch
                </code>
              </article>
            </div>
          </section>

          <section className="mt-24" aria-labelledby="read-model-title">
            <StageHeading
              number="03"
              id="read-model-title"
              title="Read model"
              detail="A denormalized snapshot optimizes the product-facing queries"
            />
            <article
              {...connectionTarget(targets.table)}
              className={`${endpointClass} mx-auto mt-5 max-w-[820px] rounded-xl border-cyan-400/35 p-4`}
            >
              <div className="flex items-start justify-between gap-6">
                <div>
                  <p className="m-0 font-mono text-[8px] font-bold uppercase tracking-wider text-cyan-300">
                    Denormalized wide table
                  </p>
                  <h3 className="m-0 mt-1 text-base font-semibold">ProjectQualitySnapshot</h3>
                </div>
                <code className="rounded border border-slate-700 bg-slate-950/40 px-2 py-1 text-[8px] text-slate-400">
                  UNIQUE(projectId, appDirPath, branch)
                </code>
              </div>
              <div className="mt-4 grid grid-cols-5 gap-2">
                {snapshotFields.map((field) => (
                  <div
                    key={field.label}
                    className={`rounded border p-2 ${toneClasses[field.tone].field}`}
                  >
                    <strong className="block text-[9px]">{field.label}</strong>
                    <span className="mt-1 block text-[7px] leading-relaxed opacity-75">
                      {field.fields}
                    </span>
                  </div>
                ))}
              </div>
            </article>
          </section>

          <section className="mt-24" aria-labelledby="consumers-title">
            <StageHeading
              number="04"
              id="consumers-title"
              title="Product reads"
              detail="One snapshot serves interactive pages, aggregates and notifications"
            />
            <div className="mx-auto mt-5 grid max-w-[760px] grid-cols-3 gap-4">
              {outputs.map(({ id, title, detail, icon: Icon }) => (
                <article
                  key={id}
                  {...connectionTarget(id)}
                  className={`${endpointClass} rounded-lg p-3 text-center`}
                >
                  <Icon aria-hidden="true" className="mx-auto size-4 text-[#41a6b9]" />
                  <h3 className="m-0 mt-2 text-[11px] font-semibold">{title}</h3>
                  <p className="m-0 mt-1 text-[8px] leading-relaxed text-slate-400">{detail}</p>
                </article>
              ))}
            </div>
          </section>
        </ConnectionSurface>
      </section>

      <ul className="m-0 mt-4 grid list-none gap-2 p-0 sm:grid-cols-3">
        <Guarantee icon={Database} title="Idempotent upsert" detail="Retries keep one clean row" />
        <Guarantee
          icon={GitBranch}
          title="Default branch only"
          detail="Feature work stays isolated"
        />
        <Guarantee
          icon={Gauge}
          title="Last successful scan"
          detail="Failures retain known-good data"
        />
      </ul>
    </figure>
  );
}

function scrollTopologyOnArrow(event: KeyboardEvent<HTMLElement>) {
  if (event.target !== event.currentTarget) return;
  const direction = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0;
  if (direction === 0) return;
  event.preventDefault();
  event.currentTarget.scrollBy({
    behavior: "auto",
    left: direction * Math.max(96, Math.round(event.currentTarget.clientWidth * 0.75)),
  });
}

function IngestLabel({ tone }: { tone: Tone }) {
  return (
    <span
      className={`inline-flex items-center gap-1 rounded border px-1.5 py-0.5 font-mono text-[7px] font-bold ${toneClasses[tone].label}`}
    >
      <Webhook aria-hidden="true" className="size-2.5" />
      POST
    </span>
  );
}

function FlowLabel({ children }: { children: ReactNode }) {
  return (
    <span className="border border-slate-600 bg-[#0b141b] px-1.5 py-0.5 font-mono text-[8px] font-bold text-slate-200">
      {children}
    </span>
  );
}

function RelationLegend() {
  const items = [
    { label: "Report ingress", color: "#41a6b9", dashed: false },
    { label: "Projection or read", color: "#94a3b8", dashed: false },
    { label: "Durable snapshot write", color: "#38bdf8", dashed: false },
    { label: "Asynchronous event", color: "#fb923c", dashed: true },
  ];
  return (
    <ul
      aria-label="Data flow relation legend"
      className="m-0 grid list-none border-y border-slate-700 p-0 text-[8px] text-slate-400 sm:grid-cols-4"
    >
      {items.map((item) => (
        <li
          key={item.label}
          className="flex items-center gap-2 px-3 py-2 sm:border-l sm:first:border-l-0"
        >
          <span
            aria-hidden="true"
            className={`w-7 border-t-2 ${item.dashed ? "border-dashed" : ""}`}
            style={{ borderColor: item.color }}
          />
          {item.label}
        </li>
      ))}
    </ul>
  );
}

function SourceCard({ source }: { source: (typeof sources)[number] }) {
  const Icon = source.icon;
  return (
    <article
      {...connectionTarget(source.id)}
      className={`${endpointClass} ${toneClasses[source.tone].border} rounded-lg p-3 text-center`}
    >
      <Icon aria-hidden="true" className={`mx-auto size-4 ${toneClasses[source.tone].icon}`} />
      <h3 className="m-0 mt-2 truncate text-[10px] font-semibold">{source.name}</h3>
      <p className="m-0 mt-1 text-[8px] text-slate-500">Scan complete</p>
    </article>
  );
}

function ModuleCard({ source }: { source: (typeof sources)[number] }) {
  return (
    <article
      {...connectionTarget(source.moduleId)}
      className={`${endpointClass} rounded-lg p-3 text-center`}
    >
      <p className={`m-0 truncate text-[9px] font-semibold ${toneClasses[source.tone].icon}`}>
        {source.module}
      </p>
      <code className="mt-1 block truncate text-[7px] text-slate-500">{source.table}</code>
    </article>
  );
}

function StageHeading({
  number,
  id,
  title,
  detail,
}: {
  number: string;
  id: string;
  title: string;
  detail: string;
}) {
  return (
    <header className="relative z-10 grid grid-cols-[30px_minmax(0,1fr)] items-center gap-3">
      <span className="grid size-[30px] place-items-center rounded border border-slate-700 bg-[#111c24] font-mono text-[8px] font-bold text-[#41a6b9]">
        {number}
      </span>
      <div>
        <h2 id={id} className="m-0 text-xs font-semibold">
          {title}
        </h2>
        <p className="m-0 mt-0.5 text-[8px] text-slate-500">{detail}</p>
      </div>
    </header>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt>{label}</dt>
      <dd className="m-0 mt-0.5 text-base font-semibold text-slate-100">{value}</dd>
    </div>
  );
}

function Comparison({
  state,
  title,
  query,
  detail,
  tone,
}: {
  state: string;
  title: string;
  query: string;
  detail: string;
  tone: "bad" | "good";
}) {
  const toneClass =
    tone === "bad"
      ? "border-rose-400/25 bg-rose-400/5 text-rose-200"
      : "border-emerald-400/25 bg-emerald-400/5 text-emerald-200";
  return (
    <article className={`rounded-lg border p-3 ${toneClass}`}>
      <p className="m-0 font-mono text-[7px] font-bold uppercase tracking-wider opacity-70">
        {state}
      </p>
      <h3 className="m-0 mt-1 text-[11px] font-semibold text-slate-100">{title}</h3>
      <code className="mt-2 block rounded bg-black/20 p-2 text-[8px]">{query}</code>
      <p className="m-0 mt-2 text-[8px] opacity-75">{detail}</p>
    </article>
  );
}

function Guarantee({
  icon: Icon,
  title,
  detail,
}: {
  icon: typeof Database;
  title: string;
  detail: string;
}) {
  return (
    <li className="flex items-center gap-2 rounded border border-slate-800 bg-[#0d151c] p-2.5">
      <Icon aria-hidden="true" className="size-3.5 shrink-0 text-[#41a6b9]" />
      <span className="min-w-0">
        <strong className="block text-[9px]">{title}</strong>
        <small className="mt-0.5 block truncate text-[7px] text-slate-500">{detail}</small>
      </span>
    </li>
  );
}
